		/* has the block been found yet? */
		if (!bkt->found) {
			/* add the reload block after blk */
			reload->next = blk->next;
			reload->prev = blk;
			blk->next = reload;
			if (reload->next)
				reload->next->prev = reload;

			/* reload is now "found" */
			bkt->found = 1;
