 * @param blk the originating instruction block
 * @param blk_tgt the target instruction block
 * @param blk_reload the new accumulator reload instruction block
 *
 * Check to see if the expected accumulator state for @blk_tgt is the same as
 * at the end of @blk.  If the two expected states are different, add an
 * explicit accumulator reload as an intermediate jump state between the two
 * instruction blocks.  @blk_reload is set to the new accumulator reload
 * instruction block if one is added, it is set to NULL otherwise.  Returns
 * zero on success, negative values on error.
 *
 */
static int _gen_bpf_acc_cond_reload(struct bpf_state *state,
				    struct bpf_blk *blk,
				    struct bpf_blk *blk_tgt,
				    struct bpf_blk **blk_reload)
{
	struct bpf_instr instr;
	struct bpf_blk *reload;
	struct bpf_hash_bkt *bkt;

	*blk_reload = NULL;

	/* do we need to reload the accumulator? */
	if ((blk_tgt->acc_start.offset != -1) &&
	    !_ACC_CMP_EQ(blk->acc_end, blk_tgt->acc_start)) {
		/* create a new instruction block for the acc reload */
		reload = _blk_alloc();
		if (!reload)
			return -ENOMEM;

		/* reload accumulator and apply a mask if needed */
		_BPF_INSTR(instr,
			   _BPF_OP(state->arch, BPF_LD + BPF_ABS),
			   _BPF_JMP_NO,
			   _BPF_JMP_NO,
			   _BPF_K(state->arch, blk_tgt->acc_start.offset));
		reload = _blk_append(state, reload, &instr);
		if (!reload)
			return -ENOMEM;
		if (blk_tgt->acc_start.mask != ARG_MASK_MAX) {
			_BPF_INSTR(instr,
				   _BPF_OP(state->arch, BPF_ALU + BPF_AND),
				   _BPF_JMP_NO,
				   _BPF_JMP_NO,
				   _BPF_K(state->arch, blk_tgt->acc_start.mask));
			reload = _blk_append(state, reload, &instr);
			if (reload == NULL)
				return -ENOMEM;
		}

		/* in some cases the jump below is unnecessary as we are simply
		 * jumping to next instruction block and can safely fall
		 * through, unfortunately we don't know that until the final
		 * stages of the bpf filter generation so go ahead and add the
		 * jump now and if we can, we'll drop it later during the
		 * final stages of filter generation */

		/* unconditionally jump to the target block */
		_BPF_INSTR(instr,
			   _BPF_OP(state->arch, BPF_JMP + BPF_JA),
			   _BPF_JMP_NO,
			   _BPF_JMP_NO,
			   _BPF_JMP_HSH(blk_tgt->hash));
		reload = _blk_append(state, reload, &instr);
		if (!reload)
			return -ENOMEM;

		/* set acc state */
		reload->acc_start = _ACC_STATE_UNDEF;
		reload->acc_end = _ACC_STATE(blk_tgt->acc_start.offset,
					     blk_tgt->acc_start.mask);

		/* check for existing hash/block, add if missing */
		if (_hsh_add_bkt(state, &reload, &bkt, 0) < 0) {
			_blk_free(state, reload);
			return -ENOMEM;
		}

		/* has the block been found yet? */
		if (!bkt->found) {
			/* add the reload block after blk */
			reload->next = blk->next;
			reload->prev = blk;
			blk->next = reload;
			if (reload->next)
				reload->next->prev = reload;

			/* reload is now "found" */
			bkt->found = 1;
		}

		/* return the new reload instruction block */
		*blk_reload = reload;

		return 0;
	}

	return -ENOENT;
}

/**
 * Generate the BPF program for the given filter collection
 * @param state the BPF state
 * @param col the filter collection
 *
 * Generate the BPF program for the given filter collection.  Returns zero on
 * success, negative values on failure.
 *
 */
static int _gen_bpf_build_bpf(struct bpf_state *state,
			      const struct db_filter_col *col)
{
	int rc;
	int iter;
	uint64_t h_val;
	unsigned int res_cnt;
	unsigned int jmp_len;
	int arch_x86_64 = -1, arch_x32 = -1;
	struct bpf_instr instr;
	struct bpf_instr *i_iter;
	struct bpf_blk *b_badarch, *b_default;
	struct bpf_blk *b_head = NULL, *b_tail = NULL, *b_iter, *b_new, *b_jmp;
	struct db_filter *db_secondary = NULL;
	struct arch_def pseudo_arch;

	/* create a fake architecture definition for use in the early stages */
	memset(&pseudo_arch, 0, sizeof(pseudo_arch));
	pseudo_arch.endian = col->endian;
	state->arch = &pseudo_arch;

	/* generate the badarch action */
	b_badarch = _gen_bpf_action(state, NULL, state->attr->act_badarch);
	if (b_badarch == NULL)
		return -ENOMEM;
	rc = _hsh_add(state, &b_badarch, 1);
	if (rc < 0)
		return rc;
	state->bad_arch_hsh = b_badarch->hash;

	/* generate the default action */
	b_default = _gen_bpf_action(state, NULL, state->attr->act_default);
	if (b_default == NULL)
		return -ENOMEM;
	rc = _hsh_add(state, &b_default, 0);
	if (rc < 0)
		return rc;
	state->def_hsh = b_default->hash;

	/* load the architecture token/number */
	_BPF_INSTR(instr, _BPF_OP(state->arch, BPF_LD + BPF_ABS),
		   _BPF_JMP_NO, _BPF_JMP_NO, _BPF_ARCH(state->arch));
	b_head = _blk_append(state, NULL, &instr);
	if (b_head == NULL)
		return -ENOMEM;
	b_head->acc_end = _ACC_STATE_OFFSET(_BPF_OFFSET_ARCH);
	rc = _hsh_add(state, &b_head, 1);
	if (rc < 0)
		return rc;
	b_tail = b_head;

	/* generate the per-architecture filters */
	for (iter = 0; iter < col->filter_cnt; iter++) {
		if (col->filters[iter]->arch->token == SCMP_ARCH_X86_64)
			arch_x86_64 = iter;
		if (col->filters[iter]->arch->token == SCMP_ARCH_X32)
			arch_x32 = iter;
	}
	for (iter = 0; iter < col->filter_cnt; iter++) {
		/* figure out the secondary arch filter mess */
		if (iter == arch_x86_64) {
			if (arch_x32 > iter)
				db_secondary = col->filters[arch_x32];
			else if (arch_x32 >= 0)
				continue;
		} else if (iter == arch_x32) {
			if (arch_x86_64 > iter)
				db_secondary = col->filters[arch_x86_64];
			else if (arch_x86_64 >= 0)
				continue;
		} else
			db_secondary = NULL;

		/* create the filter for the architecture(s) */
		b_new = _gen_bpf_arch(state, col->filters[iter], db_secondary,
				      col->attr.optimize);
		if (b_new == NULL)
			return -ENOMEM;
		b_new->prev = b_tail;
		b_tail->next = b_new;
		b_tail = b_new;
		while (b_tail->next != NULL)
			b_tail = b_tail->next;
	}

	/* add a badarch action to the end */
	b_badarch->prev = b_tail;
	b_badarch->next = NULL;
	b_tail->next = b_badarch;
	b_tail = b_badarch;

	/* reset the state to the pseudo_arch for the final resolution */
	state->arch = &pseudo_arch;

	/* resolve any TGT_NXT jumps at the top level */
	b_iter = b_head;
	do {
		for (iter = 0; iter < b_iter->blk_cnt; iter++) {
			i_iter = &b_iter->blks[iter];
			if (i_iter->jt.type == TGT_NXT) {
				b_jmp = _gen_bpf_find_nxt(b_iter,
							  i_iter->jt.tgt.nxt);
				if (b_jmp == NULL) {
					rc = -EFAULT;
					goto state_reset;
				}
				i_iter->jt = _BPF_JMP_HSH(b_jmp->hash);
			}
			if (i_iter->jf.type == TGT_NXT) {
				b_jmp = _gen_bpf_find_nxt(b_iter,
							  i_iter->jf.tgt.nxt);
				if (b_jmp == NULL) {
					rc = -EFAULT;
					goto state_reset;
				}
				i_iter->jf = _BPF_JMP_HSH(b_jmp->hash);
			}
			/* we shouldn't need to worry about a TGT_NXT in k */
		}
		b_iter = b_iter->next;
	} while (b_iter != NULL && b_iter->next != NULL);

	/* pull in all of the TGT_PTR_HSH jumps, one layer at a time */
	b_iter = b_tail;
	do {
		b_jmp = NULL;
		/* look for jumps - backwards (shorter jumps) */
		for (iter = b_iter->blk_cnt - 1;
		     (iter >= 0) && (b_jmp == NULL);
		     iter--) {
			i_iter = &b_iter->blks[iter];
