	rc = seccomp_rule_add(ctx, action, SCMP_SYS(fcntl), 0);
	if (rc != 0)
		return rc;
	rc = seccomp_rule_add(ctx, action, SCMP_SYS(lseek), 0);
	if (rc != 0)
		return rc;
	rc = seccomp_rule_add(ctx, action, SCMP_SYS(read), 0);
	if (rc != 0)
