	rc = seccomp_rule_add_arch(ctx, SCMP_ARCH_X86, SCMP_ACT_ALLOW,
				   SCMP_SYS(read), 0);
	if (rc != 0)
		goto out;
	rc = seccomp_rule_add_arch(ctx, SCMP_ARCH_X86_64, SCMP_ACT_ALLOW,
