	if (rc == 0)
		rc = _bpf_size(ctx, SCMP_ARCH_X86_64, &len_first);
	if (rc == 0)
		rc = seccomp_rule_add_arch(ctx, SCMP_ARCH_X86_64,
					   SCMP_ACT_ALLOW, SCMP_SYS(openat), 0);
	if (rc == 0)
		rc = _bpf_size(ctx, SCMP_ARCH_X86_64, &len_dup);
	if (rc == 0 && len_first != len_dup)
		rc = -EFAULT;

